const fs = require('fs');
const t = (l, f) => { try { const v = f(); console.log(l, JSON.stringify(v === undefined ? 'undef' : v)); } catch (e) { console.log(l, 'throws', e.code, e.errno, e.syscall, String(e.message).split('\n')[0]); } };
t('writeFileSync /dev/null', () => fs.writeFileSync('/dev/null', 'x'.repeat(100000)));
t('readFileSync /dev/null', () => fs.readFileSync('/dev/null').length);
t('appendFileSync /dev/stdout', () => fs.appendFileSync('/dev/stdout', 'APPEND-STDOUT\n'));
t('appendFileSync /dev/stderr', () => fs.appendFileSync('/dev/stderr', 'APPEND-STDERR\n'));
t('writeFileSync /dev/stdout', () => fs.writeFileSync('/dev/stdout', 'WRITE-STDOUT\n'));
t('openSync /dev/zero + readSync 70000', () => { const fd = fs.openSync('/dev/zero', 'r'); const b = Buffer.alloc(70000, 1); const n = fs.readSync(fd, b, 0, b.length, null); fs.closeSync(fd); return [n > 0, b.subarray(0, n).every((x) => x === 0)]; });
t('readSync /dev/urandom x64', () => { const fd = fs.openSync('/dev/urandom', 'r'); let tot = 0; for (let i = 0; i < 64; i++) tot += fs.readSync(fd, Buffer.alloc(32), 0, 32, null); fs.closeSync(fd); return tot; });
t('openSync /dev/fd/1 + writeSync', () => { const fd = fs.openSync('/dev/fd/1', 'w'); fs.writeSync(fd, 'VIA-FD1\n'); fs.closeSync(fd); });
t('statSync /dev/null', () => { const s = fs.statSync('/dev/null'); return [s.isCharacterDevice(), s.isFile(), s.isFIFO(), s.mode & 0o777]; });
t('statSync /dev/stdin (pipe or file)', () => { const s = fs.statSync('/dev/stdin'); return [s.isFIFO(), s.isFile(), s.isCharacterDevice()]; });
t('lstatSync /dev/stdout', () => fs.lstatSync('/dev/stdout').isSymbolicLink());
t('existsSync', () => [fs.existsSync('/dev/null'), fs.existsSync('/dev/zero'), fs.existsSync('/dev/nope')]);
t('openSync /dev/nope', () => fs.openSync('/dev/nope', 'r'));
t('writeSync to /dev/zero opened r', () => { const fd = fs.openSync('/dev/zero', 'r'); try { return fs.writeSync(fd, 'x'); } finally { fs.closeSync(fd); } });
t('readFileSync /dev/stdin', () => fs.readFileSync('/dev/stdin', 'utf8'));
t('error shape ENOENT', () => fs.readFileSync('/nope/x'));
t('error shape EISDIR', () => fs.readFileSync('/tmp'));
